import sys
import numpy as np

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])
    edges = [[] for _ in range(N+1)]
    for i in range(M):
        s = int(data[2 + 2*i])
        t = int(data[3 + 2*i])
        edges[s].append(t)

    # Compute expected values without blocking
    E = [0.0] * (N+1)
    for v in range(N, 0, -1):
        if v == N:
            E[v] = 0.0
        else:
            k = len(edges[v])
            E[v] = 1.0 / k
            for u in edges[v]:
                E[v] += E[u] / k

    # For each edge, try blocking it and compute E
    min_E = E[1]
    for i in range(M):
        s = int(data[2 + 2*i])
        t = int(data[3 + 2*i])
        # Check if blocking this edge would make some node unreachable
        # We need to check if there's still a path from s to N
        # Since the graph is directed and acyclic (s_i < t_i), we can use BFS
        visited = [False] * (N+1)
        queue = [s]
        visited[s] = True
        while queue:
            u = queue.pop(0)
            if u == N:
                break
            for v in edges[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        if not visited[N]:
            continue  # Blocking this edge would make N unreachable, skip

        # Compute E with this edge blocked
        new_edges = [[] for _ in range(N+1)]
        for j in range(M):
            if j == i:
                continue
            new_edges[edges[j][0]].append(edges[j][1])

        # Re-compute E with the modified graph
        E_new = [0.0] * (N+1)
        for v in range(N, 0, -1):
            if v == N:
                E_new[v] = 0.0
            else:
                if not new_edges[v]:
                    E_new[v] = float('inf')
                else:
                    k = len(new_edges[v])
                    E_new[v] = 1.0 / k
                    for u in new_edges[v]:
                        E_new[v] += E_new[u] / k

        if E_new[1] < min_E:
            min_E = E_new[1]

    print(f"{min_E:.10f}")

if __name__ == "__main__":
    main()
